import {TOWERS,ENEMIES,TERRAIN,CHAPTERS,waveSpec,towerStats,upgradeCost,healthFactor} from './content.js';
import {Game,findPath,createMap,copy} from './engine.js';
import {LEVELS,blankMap} from './levels.js';
import {BoardRenderer} from './render.js';
import {SoundBank} from './audio.js';
import {spriteHTML} from './art.js';
import {t,getLocale,setLocale,localizeDOM,initI18n} from './i18n.js';
import {OFFLINE,loadProgress,writeProgress} from './storage.js';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const compact=n=>n>=1000000?(n/1000000).toFixed(1)+'M':n>=10000?(n/1000).toFixed(1)+'k':Math.round(n).toLocaleString();
let profile={version:1,stars:{},bestEndless:0,customMaps:[],current:null,expedition:null,updatedAt:0};
let game=new Game(LEVELS[0],0),renderer=new BoardRenderer($('board'));
let ui={buildType:null,selectedTower:null,selectedCell:null,hoverCell:null,showRoutes:true,showLinks:false,pointer:null,pulseMode:false,previewRoutes:null,previewInvalid:false,isEditor:false,brush:'wall',editorSpec:null,editorReturn:null,editorPanel:true,pendingLink:null,modalPause:false,difficulty:'normal',sound:true,home:true,modalGame:null,resultShown:false,routeVersion:0};
let cloudReadOk=false,ready=false,dirty=false,saving=false,savePromise=null,saveTimer=null,lastUi=0,lastFrame=performance.now(),accumulator=0,detailKey='',paletteKey='',intelKey='',toastTimer,saveWarning=false;
const audio=new SoundBank();
function sound(type,weapon){audio.enabled=ui.sound;audio.play(type,weapon);}
function buildCost(type,cell=null){let n=TOWERS[type].cost-(cell!==null&&game.towers.some(t=>t.cell===cell&&t.type==='wall')?12:0);return game.bonus==='light'&&type!=='wall'?Math.round(n*.85):n;}
function upgradePrice(t){let n=upgradeCost(t);return game.bonus==='light'&&t.level===2?Math.round(n*1.15):n;}
let announcementTimer;
function announce(label,title,sub='',warning=false){$('announcementLabel').textContent=label;$('announcementTitle').textContent=title;$('announcementSub').textContent=sub;localizeDOM($('waveAnnouncement'));const a=$('waveAnnouncement');a.classList.remove('show');a.classList.toggle('warning',warning);void a.offsetWidth;a.classList.add('show');clearTimeout(announcementTimer);announcementTimer=setTimeout(()=>a.classList.remove('show'),2900);}
function enterBattle(){ui.home=false;document.body.classList.remove('at-home');$('gameScreen').inert=false;$('titleScreen').inert=true;audio.enabled=ui.sound;audio.unlock();renderer.resize();renderUI(true);}
function goHome(){if(game.status==='wave')game.paused=true;ui.home=true;document.body.classList.add('at-home');$('gameScreen').inert=true;$('titleScreen').inert=false;resetSelection();closeModal();renderUI(true);if(ready)save();}
function continueGame(){if(!ready){toast('正在读取进度…');return;}closeModal();enterBattle();sound('select');if(game.wave===0&&!game.towers.length)announce('OPERATION '+String(game.index+1).padStart(2,'0'),game.spec.name,'部署防线 · 守住反应堆');}
function toast(message){$('toast').textContent=t(message);$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2700);}
function invalidate(){detailKey='';paletteKey='';intelKey='';ui.previewRoutes=null;ui.previewInvalid=false;renderUI(true);}
function changed(){dirty=true;clearTimeout(saveTimer);saveTimer=setTimeout(save,500);invalidate();}
function getSave(){if(!ui.isEditor)profile.current=game.export();profile.updatedAt=Date.now();return copy(profile);}
async function save(){if(!ready)return;if(saving){await savePromise.catch(()=>{});if(dirty&&!saveWarning)return save();return;}if(!cloudReadOk){$('saveStatus').textContent=OFFLINE?'本机存档不可用 · 请导出':'存档未连接 · 可导出';$('saveStatus').classList.add('error');return;}dirty=false;saving=true;$('saveStatus').textContent='保存中…';try{savePromise=writeProgress(getSave());await savePromise;$('saveStatus').textContent=OFFLINE?'已保存到本机':'进度已保存';$('saveStatus').classList.remove('error');saveWarning=false;}catch{dirty=true;$('saveStatus').textContent='保存失败 · 可导出';$('saveStatus').classList.add('error');if(!saveWarning){toast('暂时无法保存进度，可在设置中导出存档');saveWarning=true;}}finally{saving=false;if(dirty&&!saveWarning)setTimeout(save,300);}}
async function load(){try{let p=await loadProgress();cloudReadOk=true;if(p?.version===1){profile={...profile,...p};profile.stars=p.stars||{};profile.customMaps=p.customMaps||[];if(p.current?.state){try{game=Game.restore(p.current);ui.difficulty=game.difficulty;toast('已恢复上次防线'+(game.status==='wave'?' · 战斗已暂停':''));}catch{toast('旧战斗存档无法恢复，战役星级仍保留');}}}$('saveStatus').textContent=OFFLINE?'已保存到本机':'进度已保存';}catch{$('saveStatus').textContent='存档暂不可用';$('saveStatus').classList.add('error');toast(OFFLINE?'浏览器未允许本机存档；仍可游玩并导出进度。':'存档服务暂不可用，可先游玩并导出进度');}ready=true;invalidate();}
function openModal(title,eyebrow,html){if(!$('modal').open){ui.modalPause=game.paused;ui.modalGame=game;}game.paused=true;$('modalTitle').textContent=title;$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=html;localizeDOM($('modal'));if(!$('modal').open)$('modal').showModal();}
function closeModal(){if($('modal').open)$('modal').close();if(ui.modalGame===game)game.paused=ui.home&&game.status==='wave'?true:ui.modalPause;ui.modalPause=false;ui.modalGame=null;renderUI(true);}
$('modalClose').onclick=closeModal;$('modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const b=$('modal').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal();}});
function resetSelection(){ui.buildType=null;ui.selectedTower=null;ui.selectedCell=null;ui.hoverCell=null;ui.pulseMode=false;ui.previewRoutes=null;ui.previewInvalid=false;}
function newGame(index,mode='campaign',spec=null){game=new Game(spec||LEVELS[index],index,mode,ui.difficulty,mode==='expedition'?profile.expedition?.bonus:null);if(mode==='challenge'){game.health=1;game.gold=Math.round(game.gold*.85);}if(mode==='expedition'&&profile.expedition?.carry)game.gold+=profile.expedition.carry;ui.isEditor=false;ui.resultShown=false;resetSelection();renderer.reset();closeModal();enterBattle();changed();sound('build');announce('OPERATION '+String(index+1).padStart(2,'0'),game.spec.name,'部署防线 · 守住反应堆');}
function chooseMission(index,mode='campaign'){if((game.wave>0||game.towers.length)&&!['won','lost'].includes(game.status)&&!ui.isEditor){openModal('重新部署？','MISSION CONTROL',`<p class="notice">当前阵地将被新的任务替换。已获得的战役星级会保留。</p><div class="settings-actions"><button class="primary" id="confirmMission">进入新任务</button><button class="secondary" id="keepMission">返回当前防线</button></div>`);$('confirmMission').onclick=()=>newGame(index,mode);$('keepMission').onclick=closeModal;}else newGame(index,mode);}
function campaign(){let html='<div class="modal-controls"><span>选择行动区域</span><label for="missionDifficulty">难度</label><select id="missionDifficulty"><option value="easy">休闲 · 敌人生命 75%</option><option value="normal">标准</option><option value="hard">困难 · 敌人生命 125%</option><option value="extreme">极限 · 核心 1 点</option></select><span>所有关卡可直接挑战</span></div>';for(let ch=0;ch<4;ch++){html+=`<div class="chapter-head"><span>0${ch+1}</span><strong>${CHAPTERS[ch]}</strong><span>${['造路与交叉火力','管口与伤害窗口','空间与火力复用','综合防御'][ch]}</span></div><div class="level-grid">`;for(let i=ch*6;i<ch*6+6;i++){let n=profile.stars[i]||0;html+=`<button class="level-card ${game.index===i&&game.mode==='campaign'?'current':''}" data-level="${i}"><span class="level-mini">${spriteHTML(i%6===5?'core':Object.keys(TOWERS)[i%10])}</span><span class="stars">${n?'★'.repeat(n)+'☆'.repeat(3-n):'···'}</span><span class="num">${String(i+1).padStart(2,'0')}</span><strong>${LEVELS[i].name}</strong><small>${LEVELS[i].waveCount} 波 ${i%6===5?'· 首领战':''}</small></button>`;}html+='</div>';}openModal('战役地图','CAMPAIGN / 24 MISSIONS',html);$('missionDifficulty').value=ui.difficulty;$('missionDifficulty').onchange=e=>ui.difficulty=e.target.value;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>chooseMission(Number(b.dataset.level)));}
function modes(){openModal('作战模式','OPERATIONS',`<div class="mode-grid"><div class="mode-card"><div class="mode-icon">⬡</div><h3>标准战役</h3><p>穿越四个设施区域。逐步掌握造路、管道、传送门与炮塔配合，争取无伤三星。</p><button class="primary" id="modeCampaign">选择任务</button></div><div class="mode-card"><div class="mode-icon">∞</div><h3>无尽防守</h3><p>使用当前地图与全部炮塔，抵挡不断增长的敌群。每十波遭遇首领。最佳记录：${profile.bestEndless||0} 波。</p><button class="primary" id="modeEndless">开始无尽</button></div><div class="mode-card"><div class="mode-icon">◇</div><h3>极限挑战</h3><p>当前地图，全部炮塔开放，初始资金减少 15%，核心仅有 1 点耐久。每一次漏怪都决定成败。</p><button class="primary" id="modeChallenge">接受挑战</button></div><div class="mode-card"><div class="mode-icon">⌘</div><h3>设施远征</h3><p>连续完成五场行动。选择一项专属改装，上一关剩余资金的 15% 转入下一关，最多携带 200。</p><button class="primary" id="modeExpedition">${profile.expedition?'重新开始远征':'开始远征'}</button></div></div>`);$('modeCampaign').onclick=campaign;$('modeEndless').onclick=()=>chooseMission(game.index,'endless');$('modeChallenge').onclick=()=>chooseMission(game.index,'challenge');$('modeExpedition').onclick=expeditionChoice;}
function expeditionChoice(){openModal('选择远征改装','EXPEDITION / 5 OPERATIONS',`<p class="notice">本次远征路线：冷却池、第一根管道、第一次跃迁、三面围攻、零号中枢。改装贯穿全程。</p><div class="expedition-options"><button data-bonus="longbarrel"><strong>长管炮膛</strong><span>速射塔射程 +0.6 格，攻击间隔 ×1.12。擅长长路线与反复覆盖。</span></button><button data-bonus="light"><strong>轻型基座</strong><span>一级炮塔便宜 15%，三级升级贵 15%。更快铺开整片阵地。</span></button><button data-bonus="sniper"><strong>精密工程</strong><span>狙击塔伤害提高 15%。用少量高台主力覆盖关键路线。</span></button></div>`);document.querySelectorAll('[data-bonus]').forEach(b=>b.onclick=()=>{profile.expedition={stage:0,bonus:b.dataset.bonus,carry:0};startExpeditionStage();});}
function startExpeditionStage(){let x=profile.expedition,i=[3,6,12,18,23][x.stage],m=copy(LEVELS[i]);m.waveCount=8+x.stage*2;newGame(i,'expedition',m);}
function help(){openModal('作战手册','FIELD MANUAL',`<div class="help-grid"><section class="help-section"><h3>01 / 构筑防线</h3><p>选择下方炮塔，再点击可建造的六边形。炮塔与路障会改变敌人的最短路线，但不能彻底封死入口。高台上的炮塔射程 +0.6 格。</p><p>准备阶段可建造、售出和撤销。战斗中可以升级与调整攻击优先级。旧塔售出返还 75%，未参战的新塔全额返还。</p></section><section class="help-section"><h3>02 / 地形与机关</h3><ul><li>绿色冷却池：移动速度 ×0.75。</li><li>加速轨道：移动速度 ×1.6。</li><li>管道：内部无法直接攻击，持续伤害依然有效。</li><li>空间门：A 端传送到 B 端，同一组只触发一次。</li><li>配电节点：炮塔攻击间隔 ×0.88。</li><li>闸门：在准备阶段点击，切换行进方向。</li></ul></section><section class="help-section"><h3>03 / 火力配合</h3><ul><li>冷冻 + 榴弹：延长密集敌群的受击时间。</li><li>腐蚀 + 机枪：削薄护甲后集中输出。</li><li>电磁 + 激光：先拆护盾，再照射本体。</li><li>速射、狙击、电弧、激光能对空。</li><li>雷达揭露幽影机，并提高其范围内敌人的受伤。</li></ul></section><section class="help-section"><h3>04 / 指挥与恢复</h3><ul><li>空格：开始下一波 / 暂停。</li><li>1–9、0：选择炮塔；Esc / 右键：取消。</li><li>U：升级选中塔；Z：撤销波间操作。</li><li>P：核心脉冲；R：显示 / 隐藏路线。</li><li>滚轮缩放；未选建造时拖动平移地图。</li><li>每波与战斗中自动保存；重新打开会暂停恢复。</li></ul></section></div><div class="settings-actions"><button class="secondary" id="enemyCodex">查看敌人图鉴</button><button class="primary" id="helpDone">返回战场</button></div>`);$('helpDone').onclick=closeModal;$('enemyCodex').onclick=codex;}
function codex(){openModal('敌人图鉴','HOSTILE DATABASE',`<div class="enemy-info-list">${Object.entries(ENEMIES).map(([id,e])=>`<div><div class="codex-art">${spriteHTML(id,true)}</div><strong style="color:${e.color}">${e.name}</strong><br>基础生命 ${e.hp} · 移速 ${e.speed}<br>护甲 ${e.armor||0} · 护盾 ${e.shield||0}<br>赏金 ${e.reward} · 核心伤害 ${e.leak}<br><span class="muted">${{basic:'常规地面单位。',fast:'快速穿过薄弱防线。',swarm:'大量密集出现，生命较低。',armor:'厚甲低速，适合穿甲处理。',shield:'脱战 3 秒后恢复护盾。',healer:'治疗附近受伤友军。',split:'死亡分裂出三个无赏金蜂群。',stealth:'近身或雷达范围内才可锁定。',tunnel:'管道内移动速度翻倍。',jammer:'周围炮塔攻击间隔延长 25%。',carrier:'附近友军受到伤害减少 20%。',air:'忽略地面障碍直飞核心。',boss:'半血卸甲，随后加速。',brood:'出管后释放蜂群。',twins:'两个投影共享一个生命池。',nexus:'交替获得护盾和召唤蜂群。'}[id]}</span></div>`).join('')}</div><p class="notice">生命和护盾随波次增长；移动速度与护甲保持稳定。</p>`);}
function changeLanguage(next){setLocale(next);invalidate();if($('modal').open&&$('settingsLanguage'))settings();sound('select');}
function settings(){openModal('设置与存档','COMMAND SETTINGS',`<div class="form-row"><label for="settingsLanguage">语言 / Language</label><select id="settingsLanguage"><option value="zh">简体中文</option><option value="en">English</option></select></div><div class="form-row"><label>音效</label><button class="secondary" id="settingsSound">${ui.sound?'关闭音效':'开启音效'}</button></div><div class="form-row"><label>存档状态</label><span class="notice">${esc($('saveStatus').textContent)}</span></div><p class="notice">${OFFLINE?'离线版进度保存在当前浏览器。更换设备或清理浏览器前，请导出存档备份。':'战斗与战役进度自动保存。导出文件可作为个人备份；导入会替换当前进度。关闭页面前，可点击“立即保存”确认。'}</p><div class="settings-actions"><button class="primary" id="saveNow">立即保存</button><button class="secondary" id="exportSave">导出存档</button><button class="secondary" id="importSave">导入存档</button></div><div class="panel-rule"></div><p class="notice">难度请在“战役地图”中选择，新部署后生效。标准战役星级：通关一星，核心至少 15 点二星，无漏怪三星。</p>`);$('settingsLanguage').value=getLocale();$('settingsLanguage').onchange=e=>changeLanguage(e.target.value);$('settingsSound').onclick=()=>{toggleSound();$('settingsSound').textContent=ui.sound?'关闭音效':'开启音效';};$('saveNow').onclick=async()=>{if(!cloudReadOk){try{let remote=await loadProgress();if(remote?.version===1){for(let [k,v]of Object.entries(remote.stars||{}))profile.stars[k]=Math.max(profile.stars[k]||0,v);for(let m of remote.customMaps||[])if(!profile.customMaps.some(x=>x.id===m.id))profile.customMaps.push(m);}cloudReadOk=true;}catch{toast('暂时无法连接存档，请导出备份');return;}}await save();toast(saveWarning?'暂时无法保存，请导出备份':'当前进度已保存');};$('exportSave').onclick=()=>download('hexfront-save.json',getSave());$('importSave').onclick=()=>{importKind='save';$('importInput').click();};}
function download(name,data){let url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let importKind='save';$('importInput').onchange=async e=>{let f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>1500000)throw Error('文件过大');let data=JSON.parse(await f.text());if(importKind==='map'){validateMap(data);enterEditor(data);return;}if(data.version!==1||typeof data.stars!=='object'||!Array.isArray(data.customMaps))throw Error('不是有效的六域防线存档');for(let m of data.customMaps)validateMap(m);if(data.current?.state){validateMap(data.current.state.spec);if(!Array.isArray(data.current.state.towers)||!Array.isArray(data.current.state.enemies))throw Error('战斗存档不完整');}openModal('替换当前存档？','IMPORT SAVE',`<p class="notice">将导入 ${Object.keys(data.stars).length} 关战役记录与 ${data.customMaps.length} 张自制地图。此操作会替换当前进度。</p><button class="primary" id="confirmImport">确认导入</button>`);$('confirmImport').onclick=()=>{profile=data;game=data.current?Game.restore(data.current):new Game(LEVELS[0],0);ui.isEditor=false;ui.resultShown=false;resetSelection();closeModal();changed();toast('存档已导入');};}catch(err){toast('导入失败：'+err.message);}};
function toggleSound(){ui.sound=!ui.sound;audio.enabled=ui.sound;$('homeSound').textContent='音效：'+(ui.sound?'开':'关');$('soundBtn').style.color=ui.sound?'var(--mint)':'';$('soundBtn').title=ui.sound?'关闭音效':'开启音效';try{localStorage.setItem('hexfront-audio',String(ui.sound));}catch{}if(ui.sound)sound('build');}
try{ui.sound=localStorage.getItem('hexfront-audio')!=='false';}catch{}
function selectBuild(type){if(ui.isEditor)return;sound('select');ui.buildType=ui.buildType===type?null:type;ui.selectedTower=null;ui.selectedCell=null;ui.pulseMode=false;ui.previewRoutes=null;invalidate();}
function resultAction(r,quiet=false){if(!r.ok){toast(r.error);sound('error');renderer.reject(ui.hoverCell,game.map);return false;}if(!quiet)sound('build');changed();return true;}
function startWave(){if(ui.home)return;if(ui.isEditor){testEditor();return;}if(game.status==='wave'){game.paused=!game.paused;renderUI(true);return;}if(game.status==='won'){showResult();return;}if(game.status==='lost'){retry();return;}resetSelection();resultAction(game.nextWave(),true);}
function retry(){if(game.retry().ok){ui.resultShown=false;closeModal();resetSelection();changed();toast('已恢复到本波开始前，可以重新部署');}else toast('第一波开始后才能重试');}
function restart(){openModal('重新部署本关？','REDEPLOY',`<p class="notice">重新获得初始资金，从第一波开始。已取得的战役星级会保留。</p><div class="settings-actions"><button class="primary" id="confirmRestart">重新部署</button><button class="secondary" id="cancelRestart">继续当前防线</button></div>`);$('confirmRestart').onclick=()=>newGame(game.index,game.mode,game.spec);$('cancelRestart').onclick=closeModal;}
function updatePreview(cell){ui.previewRoutes=null;ui.previewInvalid=false;if(!ui.buildType||ui.isEditor||game.status!=='build'||cell===null)return;const tile=game.map.cells[cell];if((ui.buildType==='wall'&&game.towers.some(t=>t.cell===cell))||game.gold<buildCost(ui.buildType,cell)){ui.previewInvalid=true;return;}if(!['floor','high','power'].includes(tile.type)||game.towers.some(t=>t.cell===cell&&t.type!=='wall')){ui.previewInvalid=true;return;}const ts=[...game.towers.filter(t=>t.cell!==cell),{cell}];const r=game.map.entries.map(e=>findPath(game.map,ts,e));if(r.some(x=>!x))ui.previewInvalid=true;else ui.previewRoutes=r;}
function clickBoard(cell,p){if(!ready){toast('正在读取存档，请稍等');return;}if(cell===null)return;if(ui.isEditor){paintEditor(cell);return;}if(ui.pulseMode){let q=renderer.point(p.x,p.y);if(resultAction(game.pulse(q.x,q.y),true)){ui.pulseMode=false;}return;}let tower=game.towers.find(t=>t.cell===cell);if(ui.buildType){if(tower&&tower.type!=='wall'){ui.buildType=null;ui.selectedTower=tower.id;ui.selectedCell=cell;invalidate();return;}let r=game.build(ui.buildType,cell);if(resultAction(r)){ui.selectedCell=null;updatePreview(cell);}return;}ui.selectedTower=tower?.id??null;ui.selectedCell=cell;invalidate();}
const pointers=new Map();let drag=null,pinch=null;
$('board').addEventListener('pointerdown',e=>{if(e.button===2){resetSelection();invalidate();return;}const b=$('board').getBoundingClientRect(),p={x:e.clientX-b.left,y:e.clientY-b.top};pointers.set(e.pointerId,p);$('board').setPointerCapture(e.pointerId);if(pointers.size===2){let v=[...pointers.values()];pinch={distance:Math.max(1,Math.hypot(v[0].x-v[1].x,v[0].y-v[1].y)),zoom:renderer.zoom};drag=null;}else drag={id:e.pointerId,start:p,last:p,moved:false};ui.pointer=p;ui.hoverCell=renderer.cellAt(p.x,p.y,game.map);updatePreview(ui.hoverCell);});
$('board').addEventListener('pointermove',e=>{const b=$('board').getBoundingClientRect(),p={x:e.clientX-b.left,y:e.clientY-b.top};ui.pointer=p;if(pointers.has(e.pointerId))pointers.set(e.pointerId,p);if(pointers.size===2&&pinch){let v=[...pointers.values()];renderer.zoom=Math.min(2,Math.max(.7,pinch.zoom*Math.hypot(v[0].x-v[1].x,v[0].y-v[1].y)/pinch.distance));return;}if(drag&&drag.id===e.pointerId&&pointers.size===1){if(Math.hypot(p.x-drag.start.x,p.y-drag.start.y)>7)drag.moved=true;if(drag.moved&&!ui.buildType&&!ui.isEditor&&!ui.pulseMode){renderer.pan.x+=p.x-drag.last.x;renderer.pan.y+=p.y-drag.last.y;}drag.last=p;}let cell=renderer.cellAt(p.x,p.y,game.map);if(cell!==ui.hoverCell){ui.hoverCell=cell;updatePreview(cell);}});
$('board').addEventListener('pointerup',e=>{if(drag&&drag.id===e.pointerId&&!drag.moved&&pointers.size===1){let p=drag.last,cell=renderer.cellAt(p.x,p.y,game.map);clickBoard(cell,p);}pointers.delete(e.pointerId);if(pointers.size<2)pinch=null;drag=null;});$('board').addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);drag=null;pinch=null;});$('board').addEventListener('pointerleave',()=>{ui.hoverCell=null;ui.previewRoutes=null;ui.previewInvalid=false;});$('board').addEventListener('contextmenu',e=>{e.preventDefault();resetSelection();invalidate();});$('board').addEventListener('wheel',e=>{e.preventDefault();renderer.zoom=Math.min(2,Math.max(.7,renderer.zoom+(e.deltaY<0?.1:-.1)));},{passive:false});
