function showResult(){ui.resultShown=true;const won=game.status==='won',stars=game.leaked===0?3:game.health>=15?2:1;if(won&&game.mode==='campaign'){profile.stars[game.index]=Math.max(profile.stars[game.index]||0,stars);dirty=true;}if(game.mode==='endless'){profile.bestEndless=Math.max(profile.bestEndless||0,game.wave-1);dirty=true;}let title=won?'防线稳固':'核心失守',statStars=won&&game.mode==='campaign'?`<div class="result-stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div>`:'';openModal(title,won?'MISSION COMPLETE':'SIGNAL LOST',`<div class="result"><div class="result-emblem" style="color:${won?'var(--mint)':'var(--red)'}">${spriteHTML('core')}</div>${statStars}<p>${esc(game.spec.name)} · ${won?'所有进攻已被击退':'你的防线坚持到了第 '+game.wave+' 波'}<br>${won?'这片设施暂时安全了。':'可以恢复到本波开始前，重新调整布局。'}</p><div class="result-stats"><div><strong>${game.kills}</strong><small>消灭敌人</small></div><div><strong>${compact(game.totalDamage)}</strong><small>总伤害</small></div><div><strong>${game.health}/20</strong><small>核心耐久</small></div></div><div class="result-actions">${won&&game.mode==='campaign'&&game.index<23?'<button class="primary" id="nextMission">下一关</button>':''}${won&&game.mode==='expedition'?'<button class="primary" id="nextExpedition">继续远征</button>':''}${!won?'<button class="primary" id="resultRetry">重试当前波</button>':''}${game.mode==='editor'?'<button class="primary" id="backEditor">返回编辑器</button>':''}<button class="secondary" id="resultCampaign">战役地图</button><button class="secondary" id="resultInspect">查看阵地</button></div></div>`);if($('nextMission'))$('nextMission').onclick=()=>newGame(game.index+1);if($('resultRetry'))$('resultRetry').onclick=retry;if($('backEditor'))$('backEditor').onclick=()=>enterEditor(ui.editorReturn||game.spec);if($('nextExpedition'))$('nextExpedition').onclick=()=>{profile.expedition.stage++;profile.expedition.carry=Math.min(200,Math.floor(game.gold*.15));if(profile.expedition.stage>=5){profile.expedition=null;openModal('远征完成','EXPEDITION COMPLETE','<div class="result"><div class="result-emblem">✧</div><p>五处设施全部守住。你的防御体系经受住了整个远征。</p><button class="primary" id="expDone">返回战役</button></div>');$('expDone').onclick=campaign;changed();}else startExpeditionStage();};$('resultCampaign').onclick=campaign;$('resultInspect').onclick=closeModal;save();}
let editorHistory=[];
function validateMap(m){if(!m||typeof m!=='object'||!Number.isInteger(m.width)||!Number.isInteger(m.height)||m.width<7||m.width>19||m.height<7||m.height>15)throw Error('地图尺寸须为 7–19 列、7–15 行');const point=p=>Array.isArray(p)&&p.length===2&&p.every(Number.isInteger)&&p[0]>=0&&p[0]<m.width&&p[1]>=0&&p[1]<m.height;if(!Array.isArray(m.entries)||m.entries.length<1||m.entries.length>4||!m.entries.every(point)||!point(m.exit))throw Error('需要 1–4 个入口与一个核心');for(let k of ['walls','road','coolant','high','fast','power','debris'])if(m[k]&&(!Array.isArray(m[k])||m[k].length>285||!m[k].every(point)))throw Error('地形坐标无效');if(!Number.isFinite(m.initialGold)||m.initialGold<45||m.initialGold>5000||!Number.isInteger(m.waveCount)||m.waveCount<1||m.waveCount>50)throw Error('资金须为45–5000，波数须为1–50');if((m.links||[]).length>8)throw Error('最多支持 8 条机关连接');let endpoints=new Set();for(let l of m.links||[]){if(!['pipe','portal'].includes(l.type)||!point(l.from)||!point(l.to)||!Number.isInteger(l.group)||l.group<0||l.group>2||!Number.isFinite(l.duration)||l.duration<.1||l.duration>20)throw Error('机关连接无效');for(let p of [l.from,l.to]){let k=p.join(',');if(endpoints.has(k))throw Error('机关端点不能重叠');endpoints.add(k);}}if(m.customWaves){if(!Array.isArray(m.customWaves)||m.customWaves.length>50)throw Error('波次格式无效');for(let wave of m.customWaves){if(!Array.isArray(wave)||wave.length>10)throw Error('每波最多10个小队');for(let g of wave)if(!ENEMIES[g.type]||!Number.isInteger(g.count)||g.count<1||g.count>150||!Number.isInteger(g.entry)||g.entry<0||g.entry>=m.entries.length||!Number.isFinite(g.delay)||g.delay<0||g.delay>120||!Number.isFinite(g.spacing)||g.spacing<.1||g.spacing>10)throw Error('出兵小队参数无效');}}return true;}
function editorMenu(){let custom=profile.customMaps||[];openModal('地图工坊','MAP WORKSHOP',`<p class="notice">设计六边形设施、连接管道与传送门，再为它配置资金和进攻波次。地图会随你的进度保存。</p><div class="settings-actions"><button class="primary" id="newMap">新建地图</button><button class="secondary" id="copyCurrent">复制当前地图</button><button class="secondary" id="importMap">导入地图</button></div>${custom.length?'<div class="chapter-head"><strong>我的地图</strong></div><div class="level-grid">'+custom.map((m,i)=>`<button class="level-card" data-custom="${i}"><span class="num">${String(i+1).padStart(2,'0')}</span><strong>${esc(m.name)}</strong><small>${m.width} × ${m.height} · ${m.waveCount} 波</small></button>`).join('')+'</div>':'<p class="notice">还没有自制地图。可以从空白画布开始，也可以改造当前关卡。</p>'}`);$('newMap').onclick=()=>enterEditor(blankMap());$('copyCurrent').onclick=()=>{let m=copy(game.spec);m.id='custom-'+Date.now();m.name+=' · 改造';enterEditor(m);};$('importMap').onclick=()=>{importKind='map';$('importInput').click();};document.querySelectorAll('[data-custom]').forEach(b=>b.onclick=()=>enterEditor(custom[Number(b.dataset.custom)]));}
function enterEditor(spec){if(!ui.isEditor)profile.current=game.export();ui.editorSpec=copy(spec);if(!ui.editorSpec.id?.startsWith('custom'))ui.editorSpec.id='custom-'+Date.now();game=new Game(ui.editorSpec,23,'editor');ui.isEditor=true;ui.editorPanel=true;ui.brush='wall';ui.pendingLink=null;editorHistory=[];resetSelection();renderer.reset();closeModal();enterBattle();invalidate();}
function refreshEditor(){game=new Game(ui.editorSpec,23,'editor');ui.isEditor=true;invalidate();}
function eraseAt(p){const k=p.join(',');let m=ui.editorSpec;for(let f of ['walls','road','coolant','high','fast','power','debris'])m[f]=(m[f]||[]).filter(x=>x.join(',')!==k);m.links=(m.links||[]).filter(l=>l.from.join(',')!==k&&l.to.join(',')!==k);m.gates=(m.gates||[]).filter(g=>g.at.join(',')!==k);}
function paintEditor(cell){let t=game.map.cells[cell],p=[t.c,t.r],m=ui.editorSpec,b=ui.brush;if((m.exit.join(',')===p.join(',')||m.entries.some(x=>x.join(',')===p.join(',')))&&!['entry','exit'].includes(b)){toast('入口和核心需使用对应画笔移动');return;}editorHistory.push(copy(m));if(editorHistory.length>60)editorHistory.shift();
 if(b==='entry'){if(m.exit.join(',')===p.join(',')){toast('入口不能与核心重叠');editorHistory.pop();return;}let i=m.entries.findIndex(x=>x.join(',')===p.join(','));if(i>=0){if(m.entries.length>1)m.entries.splice(i,1);else{toast('至少保留一个入口');editorHistory.pop();return;}}else if(m.entries.length<4){eraseAt(p);m.entries.push(p);}else{toast('最多四个入口');editorHistory.pop();return;}}
 else if(b==='exit'){if(m.entries.some(x=>x.join(',')===p.join(','))){toast('核心不能与入口重叠');editorHistory.pop();return;}eraseAt(p);m.exit=p;}
 else if(b==='pipe'||b==='portal'){if(!ui.pendingLink){ui.pendingLink=p;editorHistory.pop();toast('已选入口，现在选择出口');invalidate();return;}if(ui.pendingLink.join(',')===p.join(',')){ui.pendingLink=null;editorHistory.pop();invalidate();return;}let group=b==='portal'?(m.links||[]).filter(l=>l.type==='portal').length:0;if(group>2||(m.links||[]).length>=8){toast('最多 3 组空间门，合计最多 8 条连接');editorHistory.pop();return;}let from=ui.pendingLink;eraseAt(from);eraseAt(p);m.links.push({from,to:p,type:b,group,duration:b==='portal'?.4:3});ui.pendingLink=null;}
 else{eraseAt(p);if(b!=='floor'){let key=b==='wall'?'walls':b;m[key]??=[];m[key].push(p);}}refreshEditor();}
function undoEditor(){let m=editorHistory.pop();if(!m){toast('没有可撤销的编辑');return;}ui.editorSpec=m;ui.pendingLink=null;refreshEditor();}
function editorDetail(){$('detailHeading').textContent='地形画笔';$('detailIndex').textContent='MAP EDITOR';$('detailBody').innerHTML=`<h3 class="detail-name">${esc(ui.editorSpec.name)}</h3><p class="detail-desc">${game.valid()?'所有入口均可抵达核心。':'存在不可通行路线，请调整地形。'}</p><div class="editor-bar">${['floor','wall','road','coolant','high','fast','power','debris','entry','exit','pipe','portal'].map(k=>`<button class="brush ${ui.brush===k?'active':''}" data-brush="${k}">${TERRAIN[k][0]}</button>`).join('')}</div><div class="tip-box">${ui.pendingLink?'已选机关入口。下一次点击设置出口。':TERRAIN[ui.brush][1]}${ui.brush==='entry'?'<br>点击已有入口可移除；最多 4 个。':''}</div><button class="upgrade-btn" id="editorConfig">名称、资金与波次</button><button class="upgrade-btn" id="editorWaves">编辑出兵小队</button><button class="upgrade-btn" id="editorSave">保存到我的地图</button><button class="sell-btn" id="editorExport">导出地图文件</button>`;document.querySelectorAll('[data-brush]').forEach(b=>b.onclick=()=>{ui.brush=b.dataset.brush;ui.pendingLink=null;if(window.innerWidth<=760||window.innerHeight<520)ui.editorPanel=false;invalidate();});$('editorConfig').onclick=editorConfig;$('editorWaves').onclick=editorWaves;$('editorSave').onclick=saveEditor;$('editorExport').onclick=()=>download('hexfront-map.json',ui.editorSpec);}
function editorConfig(){let m=ui.editorSpec;openModal('地图设置','MAP CONFIGURATION',`<div class="form-row"><label for="mapName">地图名称</label><input id="mapName" maxlength="40" value="${esc(m.name)}"></div><div class="form-row"><label for="mapGold">初始资金</label><input id="mapGold" type="number" min="45" max="5000" value="${m.initialGold}"></div><div class="form-row"><label for="mapWaves">波次数量</label><input id="mapWaves" type="number" min="1" max="50" value="${m.waveCount}"></div><div class="form-row"><label for="mapHint">战术提示</label><input id="mapHint" maxlength="150" value="${esc(m.hint||'')}"></div><button class="primary" id="applyMapConfig">应用设置</button>`);$('applyMapConfig').onclick=()=>{let next={...m,name:$('mapName').value.trim()||'未命名地图',initialGold:Number($('mapGold').value),waveCount:Number($('mapWaves').value),hint:$('mapHint').value};try{validateMap(next);editorHistory.push(copy(m));ui.editorSpec=next;closeModal();refreshEditor();}catch(e){toast(e.message);}};}
let editingWave=1;
function editorWaves(){let m=ui.editorSpec;editingWave=Math.min(editingWave,m.waveCount);let specs=copy(m.customWaves?.[editingWave-1]||waveSpec(23,editingWave,m.waveCount,'editor'));let row=(g,i)=>`<div class="wave-edit-row form-row" data-wave-row="${i}"><select aria-label="敌人类型" data-field="type">${Object.entries(ENEMIES).map(([k,v])=>`<option value="${k}" ${k===g.type?'selected':''}>${v.name}</option>`).join('')}</select><input aria-label="数量" title="数量" data-field="count" type="number" min="1" max="150" value="${g.count}" style="width:65px"><select aria-label="入口" data-field="entry">${m.entries.map((_,i)=>`<option value="${i}" ${i===g.entry%m.entries.length?'selected':''}>入口 ${i+1}</option>`).join('')}</select><input aria-label="开始延迟" title="开始延迟（秒）" data-field="delay" type="number" min="0" max="120" value="${g.delay||0}" style="width:65px"><input aria-label="出生间隔" title="出生间隔（秒）" data-field="spacing" type="number" min=".1" max="10" step=".1" value="${g.spacing||.7}" style="width:65px"><button class="icon-btn remove-group" aria-label="删除小队">×</button></div>`;openModal('编辑出兵小队','WAVE DESIGN',`<div class="modal-controls"><label for="waveEditSelect">选择波次</label><select id="waveEditSelect">${Array.from({length:m.waveCount},(_,i)=>`<option value="${i+1}" ${i+1===editingWave?'selected':''}>第 ${i+1} 波</option>`).join('')}</select><span>类型 / 数量 / 入口 / 延迟秒数 / 出生间隔</span></div><div id="waveRows">${specs.map(row).join('')}</div><div class="settings-actions"><button class="secondary" id="addGroup">添加小队</button><button class="primary" id="applyWave">保存这一波</button></div><p class="notice">切换波次前请先保存；未编辑的波次继续使用默认进攻。最多每波 10 个小队。</p>`);function bindRemove(){document.querySelectorAll('.remove-group').forEach(b=>b.onclick=()=>b.closest('.wave-edit-row').remove());}bindRemove();$('waveEditSelect').onchange=e=>{editingWave=Number(e.target.value);editorWaves();};$('addGroup').onclick=()=>{if($('waveRows').children.length>=10){toast('每波最多10个小队');return;}$('waveRows').insertAdjacentHTML('beforeend',row({type:'basic',count:8,entry:0,delay:0,spacing:.7},99));bindRemove();};$('applyWave').onclick=()=>{let groups=[...document.querySelectorAll('.wave-edit-row')].map(r=>{let g={};for(let input of r.querySelectorAll('[data-field]'))g[input.dataset.field]=input.dataset.field==='type'?input.value:Number(input.value);return g;});if(!groups.length){toast('每波至少一个小队');return;}let next=copy(m);if(!next.customWaves)next.customWaves=Array.from({length:m.waveCount},(_,i)=>waveSpec(23,i+1,m.waveCount,'editor').map(g=>({...g,entry:g.entry%m.entries.length})));next.customWaves[editingWave-1]=groups;try{validateMap(next);editorHistory.push(copy(m));ui.editorSpec=next;closeModal();refreshEditor();toast('第 '+editingWave+' 波已保存');}catch(e){toast(e.message);}};}
function saveEditor(){try{validateMap(ui.editorSpec);if(!game.valid())throw Error('请先连通所有入口');let index=profile.customMaps.findIndex(m=>m.id===ui.editorSpec.id);if(index>=0)profile.customMaps[index]=copy(ui.editorSpec);else{if(profile.customMaps.length>=30)throw Error('最多保存 30 张地图，请导出备份');profile.customMaps.push(copy(ui.editorSpec));}changed();toast('地图已保存');}catch(e){toast(e.message);}}
function testEditor(){try{validateMap(ui.editorSpec);if(!game.valid())throw Error('至少一个入口无法抵达核心');ui.editorReturn=copy(ui.editorSpec);newGame(23,'editor',ui.editorSpec);toast('工坊测试已开始；可在战果界面返回编辑');}catch(e){toast(e.message);}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const signal=new AbortController();const tools=[{name:'read_defense_state',description:'Read the current Hexfront mission, resources, towers, enemies, and available actions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({mission:game.spec.name,status:game.status,wave:game.wave,gold:game.gold,health:game.health,energy:game.energy,map:game.map,towers:game.towers,enemies:game.enemies.map(e=>({type:e.type,x:e.x,y:e.y,hp:e.hp,shield:e.shield}))})},{name:'place_defense_tower',description:'Place a tower at a hex column and row in the current build phase, changing the same game as the visible board.',inputSchema:{type:'object',properties:{type:{type:'string',enum:Object.keys(TOWERS)},column:{type:'integer'},row:{type:'integer'}},required:['type','column','row'],additionalProperties:false},execute:input=>{if(!TOWERS[input.type]||!Number.isInteger(input.column)||!Number.isInteger(input.row)||input.column<0||input.column>=game.map.width||input.row<0||input.row>=game.map.height)throw Error('Invalid tower coordinates');if(ui.isEditor)throw Error('Finish map editing first');let r=game.build(input.type,input.row*game.map.width+input.column);if(!r.ok)throw Error(r.error);changed();return{placed:true,towerId:r.tower.id,gold:game.gold};}},{name:'start_defense_wave',description:'Start the next enemy wave from the current valid build-phase layout.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{if(ui.isEditor)throw Error('Finish map editing first');let r=game.nextWave();if(!r.ok)throw Error(r.error);changed();return{wave:game.wave,status:game.status};}}];for(let tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:signal.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>signal.abort(),{once:true});}
function frame(now){let delta=Math.min((now-lastFrame)/1000,.1);lastFrame=now;if(!$('modal').open&&!ui.isEditor&&!ui.home){accumulator+=delta*(game.speed||1);let steps=0;while(accumulator>=1/30&&steps<12){game.update(1/30);accumulator-=1/30;steps++;}}else accumulator=0;if(!ui.home&&!document.hidden){renderer.render(game,ui,now/1000);renderUI();}for(let event of game.events.splice(0)){
 sound(event.type,event.weapon);
 if(event.type==='wave'){announce('WAVE '+String(game.wave).padStart(2,'0'),'敌群来袭','防线就位 · 火力全开');}
 if(event.type==='clear'){announce('WAVE CLEARED','区域肃清','清场奖励 +'+(25+2*game.wave)+' 资金 · +20 能量');dirty=true;save();invalidate();}
 if(event.type==='win'||event.type==='lose'){if(!ui.resultShown)showResult();}
 if(event.type==='leak'){$('screenDamage').classList.remove('flash');void $('screenDamage').offsetWidth;$('screenDamage').classList.add('flash');renderer.shake=.25;}
 if(event.type==='bossKill'){announce('TARGET ELIMINATED','首领已击破','保持火力 · 清理剩余敌群');renderer.shake=.45;}
 }requestAnimationFrame(frame);}
setInterval(()=>{if(ready&&!ui.isEditor&&(game.status==='wave'||dirty))save();},12000);document.addEventListener('visibilitychange',()=>{if(document.hidden){if(game.status==='wave')game.paused=true;if(ready)save();}});window.addEventListener('pagehide',()=>{if(!ready||!cloudReadOk)return;try{writeProgress(getSave(),true).catch(()=>{});}catch{}});

function registerParentBridge(){
 if(typeof window.parent==='undefined'||window.parent===window||!globalThis.location||location.origin==='null')return;
 window.addEventListener('message',async event=>{
  if(event.origin!==location.origin||event.source!==window.parent||!event.data||typeof event.data!=='object')return;
  if(event.data.type==='ARCADE_LANGUAGE'&&['zh','en'].includes(event.data.language)){changeLanguage(event.data.language);return;}
  if(event.data.type!=='ARCADE_LEAVE'||typeof event.data.requestId!=='string'||event.data.requestId.length>128)return;
  game.paused=true;dirty=true;renderUI(true);await save();
  window.parent.postMessage({type:'ARCADE_LEAVE_READY',requestId:event.data.requestId,saved:cloudReadOk&&!saveWarning},location.origin);
 });
 window.parent.postMessage({type:'ARCADE_READY'},location.origin);
}
initI18n();load().then(registerParentBridge);registerTools();renderUI(true);requestAnimationFrame(frame);
